<?php require __DIR__.'/../app/bootstrap.php';security_headers();require_admin();$page=max(1,(int)($_GET['page']??1));$per=20;$total=(int)database()->query('SELECT COUNT(*) FROM interest_submissions')->fetchColumn();$q=database()->prepare('SELECT * FROM interest_submissions ORDER BY id DESC LIMIT ? OFFSET ?');$q->bindValue(1,$per,PDO::PARAM_INT);$q->bindValue(2,($page-1)*$per,PDO::PARAM_INT);$q->execute();$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/template/page.css"><title>Submissions</title></head><body><main class="section"><p><a href="/admin/export.php">Export CSV</a> · <form style="display:inline" method="post" action="/admin/logout.php"><input type="hidden" name="_csrf" value="<?=h(csrf_token('logout'))?>"><button>Log out</button></form></p><h1>Interest submissions</h1><p><?=h($total)?> total records</p><?php foreach($rows as $r):$p=json_decode($r['payload_json'],true)?:[];?><details><summary><?=h($r['created_at'])?> — <?=h($r['name'])?> — <?=h($r['email'])?> — <?=h($r['country'])?></summary><dl><?php foreach($p as $k=>$v):?><dt><?=h($k)?></dt><dd><?=nl2br(h($v))?></dd><?php endforeach;?></dl></details><?php endforeach;?><p><?php if($page>1):?><a href="?page=<?=$page-1?>">Previous</a><?php endif;?> <?php if($page*$per<$total):?><a href="?page=<?=$page+1?>">Next</a><?php endif;?></p></main></body></html>
